#[must_use]
pub const fn gateway_paths() -> &'static [GatewayPathKey] {
    GATEWAY_PATHS
}
#[must_use]
pub const fn gateway_routes() -> &'static [GatewayRouteSpec] {
    GATEWAY_ROUTES
}
#[must_use]
pub fn find_path(template: &str) -> Option<GatewayPathKey> {
    GATEWAY_PATHS
        .iter()
        .copied()
        .find(|path| path.template() == template)
}
#[must_use]
pub fn find_route(method: GatewayHttpMethod, template: &str) -> Option<GatewayRouteSpec> {
    GATEWAY_ROUTES
        .iter()
        .copied()
        .find(|route| route.method() == method && route.path().template() == template)
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use super::*;

    #[test]
    fn catalog_has_unique_paths_and_method_path_routes() {
        let paths = gateway_paths()
            .iter()
            .map(|path| (path.id(), path.template()))
            .collect::<BTreeSet<_>>();
        let routes = gateway_routes()
            .iter()
            .map(|route| (route.method().as_str(), route.path().template()))
            .collect::<BTreeSet<_>>();
        assert_eq!(paths.len(), GATEWAY_PATHS.len());
        assert_eq!(routes.len(), GATEWAY_ROUTES.len());
        assert_eq!(routes.len(), 482);
    }
}
